questionvariables.text:
ordergreat(x,y);

/* Generating x-coefficients which are not multiples of each other */
coeff_x1:rand_with_prohib(-10,10,[-1,0,1]);
coeff_x2:rand_with_prohib(-10,10,[-1,0,1]);
while gcd(abs(coeff_x1),abs(coeff_x2))=lmin({abs(coeff_x1),abs(coeff_x2)}) do coeff_x2:rand_with_prohib(-10,10,[-1,0,1]);

/* Generating y-coefficients which are coprime with the respective x-coefficients */
coeff_y1:rand_with_prohib(-10,10,[-1,0,1]);
coeff_y2:rand_with_prohib(-10,10,[-1,0,1]);
while gcd(abs(coeff_x1),abs(coeff_y1))>1 do coeff_y1:rand_with_prohib(-10,10,[-1,0,1]);
while gcd(abs(coeff_x2),abs(coeff_y2))>1 do coeff_y2:rand_with_prohib(-10,10,[-1,0,1]);

/* Check to ensure that the y-coefficients are not multiples of one another */
while gcd(abs(coeff_y1),abs(coeff_y2))=lmin({abs(coeff_y1),abs(coeff_y2)}) do (coeff_y1:rand_with_prohib(-10,10,[-1,0,1]),coeff_y2:rand_with_prohib(-10,10,[-1,0,1]),while gcd(abs(coeff_x1),abs(coeff_y1))>1 do coeff_y1:rand_with_prohib(-10,10,[-1,0,1]),while gcd(abs(coeff_x2),abs(coeff_y2))>1 do coeff_y2:rand_with_prohib(-10,10,[-1,0,1]));

/* Generating answers as multiples of 1/2 between -5 and 5 */
/* To ensure LHS of each equation is an integer we only allow a half to be generated if both coefficients are even */
x_ans: if integerp(coeff_x1/2) and integerp(coeff_x2/2) then rand_with_prohib(-10,10,[0])/2 else rand_with_prohib(-5,5,[0]);
y_ans: if integerp(coeff_y1/2) and integerp(coeff_y2/2) then rand_with_prohib(-10,10,[0])/2 else rand_with_prohib(-5,5,[0]);

/* Calculating the RHS of eq1 and eq2 */
eq1_ans:coeff_x1*x_ans+coeff_y1*y_ans;
eq2_ans:coeff_x2*x_ans+coeff_y2*y_ans;

/* Generating signs for question display */
eq1_sign: if coeff_y1>0 then "+" else "-";
eq2_sign: if coeff_y2>0 then "+" else "-";

/* Part (a) model answer */
/* Multiplying to give same y-coefficients */
sol_coeff_y:lcm(abs(coeff_y1),abs(coeff_y2));
eq1_fact_y:sol_coeff_y/abs(coeff_y1);
eq2_fact_y:sol_coeff_y/abs(coeff_y2);
sol_eq1_y:eq1_fact_y*coeff_x1*x + eq1_fact_y*coeff_y1*y = eq1_fact_y*eq1_ans;
sol_eq2_y:eq2_fact_y*coeff_x2*x + eq2_fact_y*coeff_y2*y = eq2_fact_y*eq2_ans;

/* Multiplying to give same x-coefficients */
sol_coeff_x:lcm(abs(coeff_x1),abs(coeff_x2));
eq1_fact_x:sol_coeff_x/abs(coeff_x1);
eq2_fact_x:sol_coeff_x/abs(coeff_x2);
sol_eq1_x:eq1_fact_x*coeff_x1*x + eq1_fact_x*coeff_y1*y = eq1_fact_x*eq1_ans;
sol_eq2_x:eq2_fact_x*coeff_x2*x + eq2_fact_x*coeff_y2*y = eq2_fact_x*eq2_ans;

feedbackvariables.text:
/* Three measures for correctness: 
Equations are equivalent to those in question
Multiplication numbers are consistent with equations given
Coefficients of x or y coordinates in both equations are the same */

/* Node 1: Check equivalence of ans2 to eq1 */
/* Node 2: Check equivalence of ans4 to eq2 (where Node 1 is correct) */
/* Node 3: Check equivalence of ans4 to eq2 (where Node 1 is incorrect)*/

/* Node 4: Check whether multiplication numbers are consistent */
implied_multiple_1:coeff(lhs(ans2),x)/coeff_x1;
implied_multiple_2:coeff(lhs(ans4),x)/coeff_x2;
check_multi_nums: if ans1=implied_multiple_1 and ans3=implied_multiple_2 then 1 else 0;

/* Node 5: If multiplication numbers are inconsistent, feedback which */
inconsistent_both: if ans1=implied_multiple_1 or ans3=implied_multiple_2 then 0 else 1;
inconsistent_which: if ans1=implied_multiple_1 then "second" else "first";

/* Node 6: Check whether either coefficients are equal */
check_equal_coeff: if abs(coeff(lhs(ans2),x))=abs(coeff(lhs(ans4),x)) or abs(coeff(lhs(ans2),y))=abs(coeff(lhs(ans4),y)) then 1 else 0;

/* Node 7: Check whether answers given are using lowest multiples possible */
check_lowest_multiple: if abs(ans1)=eq1_fact_x or abs(ans1)=eq1_fact_y then 1 else 0;

/* Partial Credit: 
Node 8: One equation and multiplier pair completely correct */

correct_eq1_check_x: if (lhs(ans2)=lhs(sol_eq1_x) and rhs(ans2)=rhs(sol_eq1_x) and ans1=eq1_fact_x) or (lhs(ans2)=-lhs(sol_eq1_x) and rhs(ans2)=-rhs(sol_eq1_x) and ans1=-eq1_fact_x) then 1 else 0;
correct_eq1_check_y: if (lhs(ans2)=lhs(sol_eq1_y) and rhs(ans2)=rhs(sol_eq1_y) and ans1=eq1_fact_y) or (lhs(ans2)=-lhs(sol_eq1_y) and rhs(ans2)=-rhs(sol_eq1_y) and ans1=-eq1_fact_y) then 1 else 0;

correct_eq2_check_x: if (lhs(ans4)=lhs(sol_eq2_x) and rhs(ans4)=rhs(sol_eq2_x) and ans3=eq2_fact_x) or (lhs(ans4)=-lhs(sol_eq2_x) and rhs(ans4)=-rhs(sol_eq2_x) and ans3=-eq2_fact_x) then 1 else 0;
correct_eq2_check_y: if (lhs(ans4)=lhs(sol_eq2_y) and rhs(ans4)=rhs(sol_eq2_y) and ans3=eq2_fact_y) or (lhs(ans4)=-lhs(sol_eq2_y) and rhs(ans4)=-rhs(sol_eq2_y) and ans3=-eq2_fact_y) then 1 else 0;

one_comp_correct_test: if correct_eq1_check_x=1 or correct_eq1_check_y=1 or correct_eq2_check_x=1 or correct_eq2_check_y=1 then 1 else 0;

/* Node 1: Check student answers with correct answers */
correct_sol_xy: if ans5=x_ans and ans6=y_ans then 1 else 0;

/* Node 2: Check whether the students system in (a) has a solution */
/* Node 3: Check whether student has correctly solved their equations from (a) */

student_ans_matrix:matrix([coeff(lhs(ans2),x),coeff(lhs(ans2),y)],[coeff(lhs(ans4),x),coeff(lhs(ans4),y)]);
student_ans_det:determinant(student_ans_matrix);
student_ans_invserse: if student_ans_det=0 then 0 else invert(student_ans_matrix);
eq_ans_matrix:matrix([rhs(ans2)],[rhs(ans4)]);
student_system_solution:student_ans_invserse.eq_ans_matrix;

consistent_sol_xy: if ans5=first(first(student_system_solution)) and ans6=first(second(student_system_solution)) then 1 else 0;

/* Node 4: Specific feedback for students who add their equations rather than subtract and vice versa */
/* Using incorrect sign to remove x-terms */

sf_x_student_ans_matrix:matrix([coeff(lhs(ans2),x),coeff(lhs(ans2),y)],[-coeff(lhs(ans4),x),coeff(lhs(ans4),y)]);
sf_x_student_ans_det:determinant(sf_x_student_ans_matrix);
sf_x_student_ans_invserse: if sf_x_student_ans_det=0 then 0 else invert(sf_x_student_ans_matrix);
sf_x_student_system_solution:sf_x_student_ans_invserse.eq_ans_matrix;
sf_x: if ans5=first(first(sf_x_student_system_solution)) and ans6=first(second(sf_x_student_system_solution)) then 1 else 0;

/* Using incorrect sign to remove y-terms */

sf_y_student_ans_matrix:matrix([coeff(lhs(ans2),x),coeff(lhs(ans2),y)],[coeff(lhs(ans4),x),-coeff(lhs(ans4),y)]);
sf_y_student_ans_det:determinant(sf_y_student_ans_matrix);
sf_y_student_ans_invserse: if sf_y_student_ans_det=0 then 0 else invert(sf_y_student_ans_matrix);
sf_y_student_system_solution:sf_y_student_ans_invserse.eq_ans_matrix;
sf_y: if ans5=first(first(sf_y_student_system_solution)) and ans6=first(second(sf_y_student_system_solution)) then 1 else 0;

specific_feedback: if sf_x=1 or sf_y=1 then 1 else 0;

/* Node 5: Worked solution is different depending on signs of coefficients */

combine_x_op: if coeff(lhs(sol_eq1_x),x)=coeff(lhs(sol_eq2_x),x) then "-" else "+";
combine_x_res: if combine_x_op="+" then (lhs(sol_eq1_x)+lhs(sol_eq2_x)=rhs(sol_eq1_x)+rhs(sol_eq2_x)) else (lhs(sol_eq1_x)-lhs(sol_eq2_x)=rhs(sol_eq1_x)-rhs(sol_eq2_x));

combine_y_op: if coeff(lhs(sol_eq1_y),y)=coeff(lhs(sol_eq2_y),y) then "-" else "+";
combine_y_res: if combine_y_op="+" then (lhs(sol_eq1_y)+lhs(sol_eq2_y)=rhs(sol_eq1_y)+rhs(sol_eq2_y)) else (lhs(sol_eq1_y)-lhs(sol_eq2_y)=rhs(sol_eq1_y)-rhs(sol_eq2_y));

/* Node 1: Check correct answer */
correct_sol_xy: if ans7=x_ans and ans8=y_ans then 1 else 0;

/* Node 2: Check consistent answer with (a) */
student_ans_matrix:matrix([coeff(lhs(ans2),x),coeff(lhs(ans2),y)],[coeff(lhs(ans4),x),coeff(lhs(ans4),y)]);
student_ans_det:determinant(student_ans_matrix);
student_ans_invserse: if student_ans_det=0 then 0 else invert(student_ans_matrix);
eq_ans_matrix:matrix([rhs(ans2)],[rhs(ans4)]);
student_system_solution:student_ans_invserse.eq_ans_matrix;

consistent_sol_a: if ans5=first(first(student_system_solution)) and ans6=first(second(student_system_solution)) then 1 else 0;

/* Node 3: Check consistent answer with (b) */
consistent_sol_b: if ans7=ans5 and ans8=ans6 then 1 else 0;
